SELECT DATE_FORMAT(c.signup_date, 'yyyy-MM') AS signup_month, SUM(CASE WHEN t.txn_type = 'CREDIT' THEN 1 ELSE 0 END) AS credit_count FROM transactions t INNER JOIN accounts a ON t.account_id = a.id INNER JOIN customers c ON a.customer_id = c.id WHERE c.segment <> 'Corporate' GROUP BY DATE_FORMAT(c.signup_date, 'yyyy-MM') HAVING SUM(CASE WHEN t.txn_type = 'CREDIT' THEN 1 ELSE 0 END) > 48 ORDER BY signup_month LIMIT 3;
